extension PenArt {
    private static var made: [String: NSImage] = [:]

    private static func image(_ svg: String?, key: String) -> NSImage? {
        if let hit = made[key] { return hit }
        guard let svg, let image = NSImage(data: Data(svg.utf8)) else { return nil }
        made[key] = image
        return image
    }

    /// The drawing a page wears: its own, Live Folders' folder, or the
    /// written page Snippets keeps its words on.
    static func name(_ page: SettingsPage) -> String {
        switch page {
        case .liveFolders: return "liveFolders"
        // Snippets: words put in at the cursor, Commands' drawing in its own yellow.
        case .snippets: return "commands"
        case .reading: return "book"
        default: return page.rawValue
        }
    }

    static func has(_ page: SettingsPage) -> Bool { ink[name(page)] != nil }

    /// The drawing for a symbol: its own, or its page's.
    static func key(_ symbol: String) -> String? {
        ink[symbol] != nil ? symbol : alias[symbol]
    }

    /// The color a page's swipe is drawn in, as drawn.
    static func color(_ page: SettingsPage) -> NSColor? {
        (mark[page.rawValue] ?? mark[name(page)]).map {
            NSColor(srgbRed: CGFloat($0 >> 16 & 0xff) / 255, green: CGFloat($0 >> 8 & 0xff) / 255,
                    blue: CGFloat($0 & 0xff) / 255, alpha: 1)
        }
    }

    /// A watch's swipe, Downloads' teal.
    static var watchColor: NSColor {
        let hex = mark["watch"] ?? 0
        return NSColor(srgbRed: CGFloat(hex >> 16 & 0xff) / 255, green: CGFloat(hex >> 8 & 0xff) / 255, blue: CGFloat(hex & 0xff) / 255, alpha: 1)
    }

    /// A page's tile, in its own colors.
    static func draw(_ page: SettingsPage, in rect: NSRect, dark: Bool, art: CGFloat = 1) {
        draw(name(page), symbol: page.icon, color: color(page), whole: page == .about, in: rect, dark: dark, art: art)
    }

    /// A tile: paper, the marker under in `color` (none for a basic), the
    /// ink over, in the current appearance. A symbol without a drawing of
    /// its own is set in ink on the same paper, so no tile is left in the
    /// old dress. `art` shrinks the drawing on its paper: a field row's
    /// tile sits among glyphs half its side, and a full one reads bigger.
    static func draw(_ key: String?, symbol: String, color: NSColor?, whole: Bool = false, in rect: NSRect, dark: Bool, art: CGFloat = 1) {
        let radius = rect.width * 0.25
        let paper = NSBezierPath(roundedRect: rect, xRadius: radius, yRadius: radius)
        PenArt.paper(dark: dark).setFill()
        paper.fill()
        let line = max(0.5, rect.width / 56)
        let rim = NSBezierPath(roundedRect: rect.insetBy(dx: line / 2, dy: line / 2),
                               xRadius: radius - line / 2, yRadius: radius - line / 2)
        rim.lineWidth = line
        PenArt.rim(dark: dark).setStroke()
        rim.stroke()
        // About's dot is whole; a swipe sits under the ink, see-through.
        let shape = key.flatMap { swipe[$0] != nil ? $0 : borrowed[$0] } ?? "ai"
        let drawn = rect.insetBy(dx: rect.width * (1 - art) / 2, dy: rect.height * (1 - art) / 2)
        if let color, let swipe = image(swipe[shape], key: shape + ".swipe") {
            // The spot is paler: a whole disc reads stronger than a stroke.
            let alpha: CGFloat = whole ? 1 : (dark ? 0.75 : 0.6) * (shape == "spot" ? 0.7 : 1)
            tinted(swipe, color, alpha: alpha, in: drawn)
        }
        let ink = dark ? NSColor(srgbRed: 0.945, green: 0.945, blue: 0.953, alpha: 1)
                       : NSColor(srgbRed: 0.11, green: 0.11, blue: 0.118, alpha: 1)
        if let key, let drawing = image(Self.ink[key], key: key) {
            tinted(drawing, ink, in: drawn)
        } else if let glyph = Glyphs.image(symbol, side: rect.width * 0.6)
                    ?? NSImage(systemSymbolName: symbol, accessibilityDescription: nil) {
            tinted(glyph, ink, in: rect.insetBy(dx: rect.width * 0.2, dy: rect.height * 0.2))
        }
    }

    /// The tile's paper, and the hairline round it.
    static func paper(dark: Bool) -> NSColor {
        dark ? NSColor(srgbRed: 0.169, green: 0.169, blue: 0.184, alpha: 1)
             : NSColor(srgbRed: 0.984, green: 0.98, blue: 0.973, alpha: 1)
    }

    static func rim(dark: Bool) -> NSColor {
        dark ? NSColor.white.withAlphaComponent(0.1) : NSColor.black.withAlphaComponent(0.1)
    }

    /// A black drawing in one color: drawn, then the color over it where
    /// it is, in a layer of its own so nothing under it is touched; the
    /// layer as a whole see-through, or the black would show in the color.
    private static func tinted(_ art: NSImage, _ color: NSColor, alpha: CGFloat = 1, in rect: NSRect) {
        guard let context = NSGraphicsContext.current?.cgContext else { return }
        context.saveGState()
        context.setAlpha(alpha)
        context.beginTransparencyLayer(in: rect, auxiliaryInfo: nil)
        art.draw(in: rect)
        color.setFill()
        rect.fill(using: .sourceAtop)
        context.endTransparencyLayer()
        context.restoreGState()
    }
}

/// A pen tile: a page's, or a symbol's over a swipe of a color.
final class PenTile: NSView {
    enum Source { case page(SettingsPage), symbol(String, NSColor?) }
    let source: Source
    var art: CGFloat = 1

    init(page: SettingsPage, art: CGFloat = 1) { source = .page(page); self.art = art; super.init(frame: .zero) }
    /// The label's color or black is ink, not a feature's: no swipe under it.
    init(symbol: String, tint: NSColor?, art: CGFloat = 1) {
        source = .symbol(symbol, tint == .labelColor || tint == .black ? nil : tint)
        self.art = art
        super.init(frame: .zero)
    }

    required init?(coder: NSCoder) { fatalError() }

    override func viewDidChangeEffectiveAppearance() {
        super.viewDidChangeEffectiveAppearance()
        needsDisplay = true
    }

    override func draw(_ dirtyRect: NSRect) {
        effectiveAppearance.performAsCurrentDrawingAppearance {
            let dark = effectiveAppearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
            switch source {
            case .page(let page): PenArt.draw(page, in: bounds, dark: dark, art: art)
            case .symbol(let symbol, let tint): PenArt.draw(PenArt.key(symbol), symbol: symbol, color: tint, in: bounds, dark: dark, art: art)
            }
        }
    }
}

/// A pen tile in SwiftUI: a page's, or a symbol's over a swipe of a color.
struct PenTileView: NSViewRepresentable {
    private let make: () -> PenTile
    var side: CGFloat = 56

    init(page: SettingsPage, side: CGFloat = 56, art: CGFloat = 1) {
        make = { PenTile(page: page, art: art) }
        self.side = side
    }

    init(symbol: String, tint: NSColor?, side: CGFloat = 28, art: CGFloat = 1) {
        make = { PenTile(symbol: symbol, tint: tint, art: art) }
        self.side = side
    }

    func makeNSView(context: Context) -> PenTile { make() }
    func updateNSView(_ view: PenTile, context: Context) {}

    func sizeThatFits(_ proposal: ProposedViewSize, nsView: PenTile, context: Context) -> CGSize? {
        CGSize(width: side, height: side)
    }
}
